const DEMO_CUSTOMERS = DEMO_CUSTOMERS_BUNDLE.customers;
const DEMO_CUSTOMER_META = DEMO_CUSTOMERS_BUNDLE.meta;
const DEMO_GHOST_CUSTOMERS = DEMO_CUSTOMERS.filter((c) => c.is_ghost);
const DEMO_LIVE_CUSTOMERS = DEMO_CUSTOMERS.filter((c) => !c.is_ghost);

function customersByGroup(group) {
  return DEMO_CUSTOMERS.filter((c) => c.group === group);
}

function toRegisterPayload(c) {
  return {
    name: c.name,
    age: c.age,
    family_size: c.family_size,
    income: c.income,
    price_range_min: c.price_range_min,
    price_range_max: c.price_range_max,
    property_type: c.property_type,
    area_interest: c.area_interest,
    options: c.options,
    phone: c.phone,
    email: c.email,
    source: c.source,
    transit_preference: c.transit_preference,
    nearest_station_interest: c.nearest_station_interest,
    preferred_channel: c.preferred_channel,
  };
}

module.exports = {
  DEMO_CUSTOMERS_BUNDLE,
  DEMO_CUSTOMERS,
  DEMO_CUSTOMER_META,
  DEMO_GHOST_CUSTOMERS,
  DEMO_LIVE_CUSTOMERS,
  customersByGroup,
  toRegisterPayload,
};
module.exports.default = DEMO_CUSTOMERS;
